  String[] audioLanguageLabels(){return new String[]{T("follow_app_language"),T("original"),languageName("nl"),languageName("en"),languageName("de"),languageName("fr"),languageName("es"),languageName("it"),languageName("pt"),languageName("tr"),languageName("pl"),languageName("ar")};}
  String[] subtitleLanguageLabels(){return new String[]{T("follow_app_language"),T("off"),languageName("nl"),languageName("en"),languageName("de"),languageName("fr"),languageName("es"),languageName("it"),languageName("pt"),languageName("tr"),languageName("pl"),languageName("ar")};}
  interface Done{void ok(boolean ok);}
  void askNewPin(Done done){EditText e=new EditText(this);e.setHint(T("pin_digits"));e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);e.setTextColor(0xFFF7F8FA);e.setHintTextColor(0xFF8D96A4);AlertDialog a=new AlertDialog.Builder(this).setTitle(T("parental_pin")).setMessage(T("pin_help")).setView(e).setNegativeButton(T("cancel"),(d,w)->done.ok(false)).setPositiveButton(T("save"),null).create();a.setOnShowListener(d->a.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{String pin=e.getText().toString().trim();if(pin.length()<4||pin.length()>8){e.setError(T("pin_digits"));return;}SettingsStore.setParentalPin(this,pin);a.dismiss();done.ok(true);}));a.show();}
  void askUnlock(Done done){EditText e=new EditText(this);e.setHint("PIN");e.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_VARIATION_PASSWORD);e.setTextColor(0xFFF7F8FA);AlertDialog a=new AlertDialog.Builder(this).setTitle(T("adult_unlock")).setView(e).setNegativeButton(T("cancel"),(d,w)->done.ok(false)).setPositiveButton(T("unlock"),null).create();a.setOnShowListener(d->a.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(v->{if(SettingsStore.unlockAdults(this,e.getText().toString().trim())){a.dismiss();done.ok(true);}else e.setError(T("wrong_pin"));}));a.show();}
