  void spin(String l,String k,String[]ls,String[]vs){TextView z=t(l,13);z.setTextColor(0xFFA7AFBC);box.addView(z);Spinner sp=new Spinner(this);ArrayAdapter<String>ad=new ArrayAdapter<String>(this,android.R.layout.simple_spinner_item,ls){@Override public View getDropDownView(int q,View v,ViewGroup g){TextView x=(TextView)super.getDropDownView(q,v,g);x.setTextColor(0xFFF7F8FA);x.setBackgroundColor(0xFF181C22);x.setPadding(dp(16),dp(14),dp(16),dp(14));return x;}};ad.setDropDownViewResource(android.R.layout.simple_spinner_dropdown_item);sp.setAdapter(ad);String cur=p.getString(k,vs[0]);int n=0;for(int i=0;i<vs.length;i++)if(vs[i].equals(cur))n=i;sp.setSelection(n,false);final boolean[] ready={false};sp.post(()->ready[0]=true);sp.setOnItemSelectedListener(new AdapterView.OnItemSelectedListener(){public void onNothingSelected(AdapterView<?>x){}public void onItemSelected(AdapterView<?>x,View v,int q,long id){if(!ready[0])return;String next=vs[q];String old=p.getString(k,vs[0]);if(next.equals(old))return;if("language".equals(k)){SettingsStore.setPrimaryLanguage(SettingsActivity.this,next);recreate();}else p.edit().putString(k,next).apply();}});box.addView(sp,new LinearLayout.LayoutParams(-1,dp(48)));}
